// @FIGURE_CODE_BEGIN
/* ── element spec ───────────────────────────────────────────────────────────
   slab            → BoxGeometry(5.0, 0.35, 3.6), top #3E8C22 / sides #2E7A1E
   edge highlight  → LineLoop rectangle at y=0, #C8D64B
   Ni lattice      → InstancedMesh hemisphere SphereGeometry(0.32,…,0,PI/2) 7×5 green
   pick halo       → TorusGeometry(0.40,0.025) orange, follows picked instance
   free H2         → 2 × SphereGeometry(0.20) white + CylinderGeometry rod
   surface H ×6    → SphereGeometry(0.20) white  (y = +0.22 hollows)
   carbons ×2      → SphereGeometry(0.33) charcoal #3A3A3A
   molecular H ×6  → SphereGeometry(0.20) white
   C–C rods ×2     → CylinderGeometry(0.055) grey  (2nd = π rod, fades out)
   C–H rods ×6     → CylinderGeometry(0.055) grey
   Ni–C bonds ×2   → dashed Line, grey, faint
   arrow (a)       → ArrowHelper pointing down at the H2
   arrows (b) ×3   → ArrowHelper pointing down onto the adsorbed ethylene
   arrows (c) ×2   → TubeGeometry(QuadraticBezierCurve3) + ConeGeometry, black
   arrow (d)       → TubeGeometry(QuadraticBezierCurve3) + ConeGeometry, black
   labels          → addLabel + thin black Line leaders
──────────────────────────────────────────────────────────────────────────── */

const V = (x, y, z) => new THREE.Vector3(x, y, z);
const clamp01 = v => Math.max(0, Math.min(1, v));

/* ── lighting ─────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.58));
const key = new THREE.DirectionalLight(0xffffff, 0.85);
key.position.set(4, 7, 5);
scene.add(key);
const fill = new THREE.DirectionalLight(0xffffff, 0.28);
fill.position.set(-5, 3, -4);
scene.add(fill);

/* ── slab ─────────────────────────────────────────────────────────────── */
const SLAB_W = 5.0, SLAB_T = 0.35, SLAB_D = 3.6;
const sideMat = new THREE.MeshPhongMaterial({ color: 0x2E7A1E, shininess: 20 });
const topMat = new THREE.MeshPhongMaterial({ color: 0x3E8C22, shininess: 25 });
const botMat = new THREE.MeshPhongMaterial({ color: 0x235E16, shininess: 10 });
const slab = new THREE.Mesh(
  new THREE.BoxGeometry(SLAB_W, SLAB_T, SLAB_D),
  [sideMat, sideMat, topMat, botMat, sideMat, sideMat]
);
slab.position.y = -SLAB_T / 2;
scene.add(slab);

const hw = SLAB_W / 2 - 0.004, hd = SLAB_D / 2 - 0.004;
const rim = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints([
    V(-hw, 0.004, -hd), V(hw, 0.004, -hd), V(hw, 0.004, hd), V(-hw, 0.004, hd)
  ]),
  new THREE.LineBasicMaterial({ color: 0xC8D64B })
);
scene.add(rim);

/* ── Ni lattice (instanced hemispheres) ───────────────────────────────── */
const NI_R = 0.32, NX = 7, NZ = 5, SPX = 0.68, SPZ = 0.72;
const niGeo = new THREE.SphereGeometry(NI_R, 20, 12, 0, Math.PI * 2, 0, Math.PI / 2);
const niMat = new THREE.MeshPhongMaterial({ color: 0xffffff, specular: 0xA9DD84, shininess: 55 });
const niMesh = new THREE.InstancedMesh(niGeo, niMat, NX * NZ);
const niPositions = [];
const GREEN = new THREE.Color(0x4FA22E);
const HILITE = new THREE.Color(0xFF8C3A);
{
  const m = new THREE.Matrix4();
  let k = 0;
  for (let j = 0; j < NZ; j++) {
    for (let i = 0; i < NX; i++) {
      const x = (i - (NX - 1) / 2) * SPX + (j % 2 ? 0.17 : -0.17);
      const z = (j - (NZ - 1) / 2) * SPZ;
      const p = V(x, -0.03, z);
      niPositions.push(p);
      m.makeTranslation(p.x, p.y, p.z);
      niMesh.setMatrixAt(k, m);
      niMesh.setColorAt(k, GREEN);
      k++;
    }
  }
  niMesh.instanceMatrix.needsUpdate = true;
  if (niMesh.instanceColor) niMesh.instanceColor.needsUpdate = true;
}
scene.add(niMesh);

const halo = new THREE.Mesh(
  new THREE.TorusGeometry(0.40, 0.025, 8, 36),
  new THREE.MeshBasicMaterial({ color: 0xFF8C3A })
);
halo.rotation.x = -Math.PI / 2;
halo.visible = false;
scene.add(halo);

/* ── shared atom / bond factories ─────────────────────────────────────── */
const H_R = 0.20, C_R = 0.33, ROD_R = 0.055;
const hGeo = new THREE.SphereGeometry(H_R, 22, 16);
const cGeo = new THREE.SphereGeometry(C_R, 26, 20);
const rodGeo = new THREE.CylinderGeometry(ROD_R, ROD_R, 1, 14);
const UPV = V(0, 1, 0);

function mkH() {
  const m = new THREE.Mesh(hGeo, new THREE.MeshPhongMaterial({
    color: 0xF2F2F2, specular: 0xffffff, shininess: 95, transparent: true
  }));
  scene.add(m); return m;
}
function mkC() {
  const m = new THREE.Mesh(cGeo, new THREE.MeshPhongMaterial({
    color: 0x3A3A3A, specular: 0x9a9a9a, shininess: 80, transparent: true
  }));
  scene.add(m); return m;
}
function mkRod() {
  const m = new THREE.Mesh(rodGeo, new THREE.MeshPhongMaterial({
    color: 0xCCCCCC, specular: 0xffffff, shininess: 50, transparent: true
  }));
  scene.add(m); return m;
}
const _dv = new THREE.Vector3();
function setRod(mesh, a, b, offset) {
  _dv.subVectors(b, a);
  const len = _dv.length();
  if (len < 1e-5) { mesh.visible = false; return; }
  mesh.position.copy(a).addScaledVector(_dv, 0.5);
  if (offset) mesh.position.add(offset);
  mesh.quaternion.setFromUnitVectors(UPV, _dv.clone().normalize());
  mesh.scale.set(1, len, 1);
}
function setOp(mesh, o) { mesh.material.opacity = o; mesh.visible = o > 0.02; }

/* ── molecular geometry constants ─────────────────────────────────────── */
const e1 = V(1, 0, 0);
const e2 = V(0, 0.94, -0.34).normalize();
const D = (a, b) => e1.clone().multiplyScalar(a).addScaledVector(e2, b).normalize();
const CH = 0.62, HALF_CC = 0.45;

function freeEthylene(center) {
  const c0 = center.clone().add(V(-HALF_CC, 0, 0));
  const c1 = center.clone().add(V(HALF_CC, 0, 0));
  return {
    c0, c1, h: [
      c0.clone().addScaledVector(D(-0.5, 0.866), CH),
      c0.clone().addScaledVector(D(-0.5, -0.866), CH),
      c1.clone().addScaledVector(D(0.5, 0.866), CH),
      c1.clone().addScaledVector(D(0.5, -0.866), CH)
    ]
  };
}
function ethane(center) {
  const c0 = center.clone().add(V(-HALF_CC, 0, 0));
  const c1 = center.clone().add(V(HALF_CC, 0, 0));
  const mk = (c, sx, adeg) => {
    const a = THREE.MathUtils.degToRad(adeg);
    return c.clone().addScaledVector(V(0.333 * sx, 0.943 * Math.cos(a), 0.943 * Math.sin(a)), CH);
  };
  return {
    c0, c1, h: [
      mk(c0, -1, 90), mk(c0, -1, 210), mk(c1, 1, 30), mk(c1, 1, 150),
      mk(c0, -1, 330), mk(c1, 1, 270)
    ]
  };
}

const ADS_C0 = V(-HALF_CC, 0.55, 0), ADS_C1 = V(HALF_CC, 0.55, 0);
const ADS_H = [
  ADS_C0.clone().addScaledVector(V(-0.5, 0.5, 0.71).normalize(), CH),
  ADS_C0.clone().addScaledVector(V(-0.5, 0.5, -0.71).normalize(), CH),
  ADS_C1.clone().addScaledVector(V(0.5, 0.5, 0.71).normalize(), CH),
  ADS_C1.clone().addScaledVector(V(0.5, 0.5, -0.71).normalize(), CH)
];
const ADS_H4 = ADS_C0.clone().addScaledVector(V(-0.9, 0.44, 0).normalize(), CH);
const ADS_H5 = ADS_C1.clone().addScaledVector(V(0.9, 0.44, 0).normalize(), CH);

const FREE_C = V(0, 2.35, 0.2);
const ETHANE_C = V(0, 2.00, 0.2);
const EXIT_C = V(0, 3.25, 0.2);
const FREE = freeEthylene(FREE_C);
const ETH = ethane(ETHANE_C);
const EXIT = ethane(EXIT_C);

/* surface hollow slots */
const S = [
  V(-1.90, 0.22, 0.90),   // 0
  V(-1.40, 0.22, 0.50),   // 1  migrator → C0
  V(1.40, 0.22, -0.50),   // 2  migrator → C1 (H2 landing site)
  V(2.00, 0.22, -1.05),   // 3  (H2 landing site)
  V(-1.80, 0.22, -0.85),  // 4
  V(2.15, 0.22, 0.60)     // 5
];

/* free H2 */
const HC = V(1.55, 1.50, -0.75);
const HD = V(0.82, 0.50, 0.28).normalize();
const H2A = HC.clone().addScaledVector(HD, 0.21);
const H2B = HC.clone().addScaledVector(HD, -0.21);

/* ── meshes ───────────────────────────────────────────────────────────── */
const mH2A = mkH(), mH2B = mkH(), mH2Rod = mkRod();
const mS = S.map(() => mkH());
const mC0 = mkC(), mC1 = mkC();
const mMolH = [0, 1, 2, 3, 4, 5].map(() => mkH());
const mCCa = mkRod(), mCCb = mkRod();
const mCH = [0, 1, 2, 3, 4, 5].map(() => mkRod());

function mkDashed() {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
  const l = new THREE.Line(g, new THREE.LineDashedMaterial({
    color: 0x888888, dashSize: 0.09, gapSize: 0.07, transparent: true
  }));
  l.userData.set = (a, b) => {
    const p = g.attributes.position;
    p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z);
    p.needsUpdate = true; l.computeLineDistances(); g.computeBoundingSphere();
  };
  scene.add(l); return l;
}
const niC0 = mkDashed(), niC1 = mkDashed();

/* ── arrows ───────────────────────────────────────────────────────────── */
function mkStraightArrow(origin, len) {
  const a = new THREE.ArrowHelper(V(0, -1, 0), origin, len, 0x111111, 0.26, 0.17);
  a.line.material.transparent = true;
  a.cone.material.transparent = true;
  a.line.material.linewidth = 2;
  a.userData.setOp = o => {
    a.line.material.opacity = o; a.cone.material.opacity = o; a.visible = o > 0.02;
  };
  scene.add(a); return a;
}
const arrowA = mkStraightArrow(V(1.55, 1.14, -0.75), 0.82);
const arrowsB = [-0.95, 0, 0.95].map(x => mkStraightArrow(V(x, 2.05, 0.2), 0.82));

function mkCurvedArrow(p0, p1, p2) {
  const curve = new THREE.QuadraticBezierCurve3(p0, p1, p2);
  const mat = new THREE.MeshBasicMaterial({ color: 0x111111, transparent: true });
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 28, 0.032, 8, false), mat);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.085, 0.22, 14), mat.clone());
  const tan = curve.getTangent(1).normalize();
  cone.position.copy(p2).addScaledVector(tan, 0.08);
  cone.quaternion.setFromUnitVectors(UPV, tan);
  const g = new THREE.Group();
  g.add(tube); g.add(cone);
  g.userData.setOp = o => {
    tube.material.opacity = o; cone.material.opacity = o; g.visible = o > 0.02;
  };
  scene.add(g); return g;
}
const arrowCL = mkCurvedArrow(V(-1.48, 0.42, 0.48), V(-1.40, 0.95, 0.26), V(-1.16, 0.86, 0.06));
const arrowCR = mkCurvedArrow(V(1.48, 0.42, -0.48), V(1.40, 0.95, -0.26), V(1.16, 0.86, -0.06));
const arrowD = mkCurvedArrow(V(1.25, 0.48, 0.95), V(0.95, 1.38, 0.62), V(0.38, 1.72, 0.36));

/* ── keyframes ────────────────────────────────────────────────────────── */
const K = [
  { // 0 — state (a)
    hA: H2A, hB: H2B, hAop: 1, hBop: 1,
    sOp: [1, 1, 0, 0, 1, 1],
    c0: FREE.c0, c1: FREE.c1,
    h: [FREE.h[0], FREE.h[1], FREE.h[2], FREE.h[3], S[1], S[2]],
    hop: [1, 1, 1, 1, 0, 0]
  },
  { // 1 — state (b)
    hA: S[2], hB: S[3], hAop: 0, hBop: 0,
    sOp: [1, 1, 1, 1, 1, 1],
    c0: ADS_C0, c1: ADS_C1,
    h: [ADS_H[0], ADS_H[1], ADS_H[2], ADS_H[3], S[1], S[2]],
    hop: [1, 1, 1, 1, 0, 0]
  },
  { // 2 — state (c)
    hA: S[2], hB: S[3], hAop: 0, hBop: 0,
    sOp: [1, 0, 0, 1, 1, 1],
    c0: ADS_C0, c1: ADS_C1,
    h: [ADS_H[0], ADS_H[1], ADS_H[2], ADS_H[3], ADS_H4, ADS_H5],
    hop: [1, 1, 1, 1, 1, 1]
  },
  { // 3 — state (d)
    hA: H2A, hB: H2B, hAop: 0, hBop: 0,
    sOp: [0, 0, 0, 1, 1, 0],
    c0: ETH.c0, c1: ETH.c1,
    h: ETH.h.slice(),
    hop: [1, 1, 1, 1, 1, 1]
  },
  { // 4 — wraps back to (a)
    hA: H2A, hB: H2B, hAop: 1, hBop: 1,
    sOp: [1, 1, 0, 0, 1, 1],
    c0: EXIT.c0, c1: EXIT.c1,
    h: EXIT.h.slice(),
    hop: [1, 1, 1, 1, 1, 1]
  }
];

/* ── labels + leader lines ────────────────────────────────────────────── */
function mkLeader() {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
  const l = new THREE.Line(g, new THREE.LineBasicMaterial({ color: 0x111111, transparent: true }));
  l.userData.set = (a, b) => {
    const p = g.attributes.position;
    p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z);
    p.needsUpdate = true; g.computeBoundingSphere();
  };
  scene.add(l); return l;
}
const leadNi = mkLeader(); leadNi.userData.set(V(-2.20, 1.18, 1.22), V(-0.90, 0.06, 0.35));
const leadH = mkLeader(); leadH.userData.set(V(1.68, 2.16, -1.58), HC.clone().add(V(0, 0.18, 0)));
const leadMol = mkLeader(); leadMol.userData.set(V(-1.2, 2.9, 1.2), V(-0.5, 2.5, 0.3));

const lblNi = addLabel('Ni surface', V(-2.45, 1.35, 1.35), { fontSize: '13px' });
const lblH = addLabel('Hydrogen', V(1.78, 2.34, -1.72), { fontSize: '13px' });
const lblMol = addLabel('Ethylene', V(-1.3, 3.0, 1.3), { fontSize: '13px' });
const lblCap = addLabel('(a)', V(1.80, -1.45, 1.80), { fontSize: '16px' });

/* ── state machine ────────────────────────────────────────────────────── */
let curP = 0, targetP = 0, wrapForward = false, playing = false, speed = 0.5;
const STEP_TITLES = [
  '(a) Hydrogen adsorbs and dissociates',
  '(b) Ethylene adsorbs, π bond breaks',
  '(c) Surface hydrogens migrate and add',
  '(d) Ethane desorbs'
];
const STEP_BODY = [
  'An H₂ molecule drops onto the nickel lattice; the H–H bond breaks and two separate H atoms sit bonded in surface hollows.',
  'Ethylene descends onto the surface. Its C=C π bond opens, leaving a C–C single bond with each carbon now bonded to Ni and the hydrogens bent upward.',
  'Adsorbed H atoms diffuse across the nickel and collide with the bound carbons; curved arrows show each new C–H bond forming as the Ni–C bonds weaken.',
  'With both carbons saturated, ethane no longer binds the metal and lifts off, leaving the nickel surface unchanged and available for the next cycle.'
];

const _t0 = new THREE.Vector3(), _t1 = new THREE.Vector3();
const _hp = [0, 1, 2, 3, 4, 5].map(() => new THREE.Vector3());
const _molCenter = new THREE.Vector3();
const _anchor = new THREE.Vector3(), _lend = new THREE.Vector3();

function win(p, c) {
  const dd = Math.min(Math.abs(p - c), Math.abs(p - c + 4), Math.abs(p - c - 4));
  return clamp01((0.44 - dd) / 0.26);
}

function applyState(p) {
  const pp = Math.max(0, Math.min(3.9999, p));
  const s = Math.floor(pp), ur = pp - s, u = ur * ur * (3 - 2 * ur);
  const A = K[s], B = K[s + 1];
  const L = (a, b) => a + (b - a) * u;

  // channel overrides
  const molOp = s === 0 ? clamp01(ur * 3.5)
    : s === 3 ? clamp01(1 - (ur - 0.35) / 0.35) : 1;
  const pi = s === 0 ? clamp01(1 - (ur - 0.50) / 0.30)
    : s === 3 ? clamp01((ur - 0.60) / 0.30) : 0;
  const niOp = s === 0 ? clamp01((ur - 0.72) / 0.20) * 0.9
    : s === 1 ? 0.9 - 0.4 * u
      : s === 2 ? 0.5 * clamp01(1 - ur * 1.6) : 0;

  // free H2
  _t0.copy(A.hA).lerp(B.hA, u); mH2A.position.copy(_t0);
  _t1.copy(A.hB).lerp(B.hB, u); mH2B.position.copy(_t1);
  const h2op = L(A.hAop, B.hAop);
  setOp(mH2A, h2op); setOp(mH2B, L(A.hBop, B.hBop));
  setRod(mH2Rod, _t0, _t1);
  setOp(mH2Rod, Math.min(h2op, L(A.hBop, B.hBop)));

  // surface hydrogens
  for (let i = 0; i < 6; i++) {
    mS[i].position.copy(S[i]);
    setOp(mS[i], L(A.sOp[i], B.sOp[i]));
  }

  // molecule
  _t0.copy(A.c0).lerp(B.c0, u); mC0.position.copy(_t0);
  _t1.copy(A.c1).lerp(B.c1, u); mC1.position.copy(_t1);
  setOp(mC0, molOp); setOp(mC1, molOp);
  _molCenter.copy(_t0).add(_t1).multiplyScalar(0.5);

  const off = e2.clone().multiplyScalar(0.07 * pi);
  setRod(mCCa, _t0, _t1, off); setOp(mCCa, molOp);
  setRod(mCCb, _t0, _t1, off.clone().multiplyScalar(-1)); setOp(mCCb, molOp * pi);

  for (let i = 0; i < 6; i++) {
    _hp[i].copy(A.h[i]).lerp(B.h[i], u);
    mMolH[i].position.copy(_hp[i]);
    const o = molOp * L(A.hop[i], B.hop[i]);
    setOp(mMolH[i], o);
    setRod(mCH[i], (i === 0 || i === 1 || i === 4) ? _t0 : _t1, _hp[i]);
    setOp(mCH[i], o);
  }

  // Ni–C dashed bonds
  niC0.userData.set(_t0, V(_t0.x - 0.10, 0.12, _t0.z + 0.05));
  niC1.userData.set(_t1, V(_t1.x + 0.10, 0.12, _t1.z - 0.05));
  niC0.material.opacity = niOp; niC0.visible = niOp > 0.02;
  niC1.material.opacity = niOp; niC1.visible = niOp > 0.02;

  // arrows
  const oa = win(pp, 0), ob = win(pp, 1), oc = win(pp, 2), od = win(pp, 3);
  arrowA.userData.setOp(oa);
  arrowsB.forEach(a => a.userData.setOp(ob));
  arrowCL.userData.setOp(oc); arrowCR.userData.setOp(oc);
  arrowD.userData.setOp(od);

  // labels
  lblH.div.style.opacity = String(oa);
  leadH.material.opacity = oa; leadH.visible = oa > 0.02;

  const adsorbed = pp > 1.15 && pp < 2.85;
  if (adsorbed) {
    _anchor.set(1.55, -0.50, 1.55);
    _lend.set(0.25, 0.55, 0.32);
    lblMol.div.innerHTML = 'Ethylene adsorbed on<br>surface breaking &pi; bonds';
  } else {
    _anchor.copy(_molCenter).add(V(-1.30, 0.82, 1.30));
    _lend.copy(_molCenter).add(V(-0.50, 0.36, 0.18));
    lblMol.div.innerHTML = (pp > 2.85) ? 'Ethane (C<sub>2</sub>H<sub>6</sub>)' : 'Ethylene';
  }
  lblMol.pos.copy(_anchor);
  lblMol.div.style.opacity = String(molOp);
  leadMol.userData.set(_anchor.clone().addScaledVector(_lend.clone().sub(_anchor).normalize(), 0.30), _lend);
  leadMol.material.opacity = molOp; leadMol.visible = molOp > 0.02;

  const capIdx = Math.round(pp) % 4;
  lblCap.div.innerHTML = ['(a)', '(b)', '(c)', '(d)'][capIdx];
}

/* ── initial pose + camera ────────────────────────────────────────────── */
applyState(0);
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.6
});

/* ── Ni atom picking ──────────────────────────────────────────────────── */
let pickedIdx = -1;
registerInteractive(niMesh, {
  title: 'Ni — surface atom',
  tooltip: 'Ni — surface atom',
  body: 'Each bump is a nickel atom. Its partially filled d-orbitals overlap with H₂ and with the ethylene π cloud, weakening the H–H and C=C bonds so they break at far lower temperature than in the gas phase. The Ni–H and Ni–C bonds formed here hold the fragments next to each other until they combine.',
  onClick: (hit) => {
    if (hit && typeof hit.instanceId === 'number') {
      if (pickedIdx >= 0) niMesh.setColorAt(pickedIdx, GREEN);
      pickedIdx = hit.instanceId;
      niMesh.setColorAt(pickedIdx, HILITE);
      niMesh.instanceColor.needsUpdate = true;
      const p = niPositions[pickedIdx];
      halo.position.set(p.x, 0.02, p.z);
      halo.visible = true;
    }
  }
});

/* ── UI wiring ────────────────────────────────────────────────────────── */
document.getElementById('btnReset').style.display = '';
const btns = ['stepA', 'stepB', 'stepC', 'stepD'].map(id => document.getElementById(id));
const narrTitle = document.getElementById('narrTitle');
const narrBody = document.getElementById('narrBody');
const btnPlay = document.getElementById('btnPlay');
let shownStep = -1;

function refreshUI(idx) {
  if (idx === shownStep) return;
  shownStep = idx;
  btns.forEach((b, i) => b.classList.toggle('active', i === idx));
  narrTitle.textContent = STEP_TITLES[idx];
  narrBody.textContent = STEP_BODY[idx];
}
refreshUI(0);

function goToStep(i) {
  playing = false;
  btnPlay.textContent = '▶ Play catalytic cycle';
  btnPlay.classList.remove('active');
  if (i === 0 && curP > 2.2) { targetP = 4; wrapForward = true; }
  else { targetP = i; wrapForward = false; }
