<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;font-size:13px;line-height:1.3;">Ni‑catalysed hydrogenation<br><span style="font-weight:400;font-size:12px">C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub> → C<sub>2</sub>H<sub>6</sub></span></div>
