// @FIGURE_CODE_BEGIN
/* ── element spec ───────────────────────────────────────────────────────────
   slab             → BoxGeometry(5.0, 0.35, 3.6)  top #46A028 / sides #2E7A1E
   edge highlight   → LineLoop rectangle y=0, #C8D64B
   Ni lattice       → InstancedMesh hemisphere SphereGeometry(0.32,..,0,PI/2) 7x5, #5FBE34
   pick halo        → TorusGeometry(0.40,0.025) orange, follows picked instance
   free H2 (x2)     → 2 x SphereGeometry(0.185) WHITE, centres 0.48 apart + grey rod between
   surface H x8     → SphereGeometry(0.185) white, y=+0.22, inside slab footprint
   carbons x2       → SphereGeometry(0.33) charcoal #3A3A3A
   molecular H x6   → SphereGeometry(0.185) white
   C–C rods x2      → CylinderGeometry(0.055) light grey (2nd = pi rod, fades out in b)
   C–H rods x6      → CylinderGeometry(0.055) light grey
   Ni–C bonds x2    → dashed Line grey, faint
   arrows (a) x2    → ArrowHelper down, length 0.90
   arrows (b) x3    → ArrowHelper down, length 1.05
   arrows (c) x2    → TubeGeometry(QuadraticBezierCurve3) + ConeGeometry, black
   arrow  (d)       → TubeGeometry(QuadraticBezierCurve3) + ConeGeometry, black
   all-stages strip → 4 static mini panels (scale 0.45) laid out along screen-x
   labels           → addLabel + thin black Line leaders
──────────────────────────────────────────────────────────────────────────── */

const V = (x, y, z) => new THREE.Vector3(x, y, z);
const clamp01 = v => Math.max(0, Math.min(1, v));
const UPV = V(0, 1, 0);

/* ── lighting: bright so whites read WHITE and greens read VIVID ───────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.78));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.85);
keyLight.position.set(4, 7, 5);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.30);
fillLight.position.set(-5, 3, -4);
scene.add(fillLight);

/* ── shared geometry / materials ──────────────────────────────────────── */
const SLAB_W = 5.0, SLAB_T = 0.35, SLAB_D = 3.6;
const NI_R = 0.32, NX = 7, NZ = 5, SPX = 0.68, SPZ = 0.72;

const slabGeo = new THREE.BoxGeometry(SLAB_W, SLAB_T, SLAB_D);
const sideMat = new THREE.MeshPhongMaterial({ color: 0x2E7A1E, emissive: 0x0d2608, specular: 0x224018, shininess: 8 });
const topMat = new THREE.MeshPhongMaterial({ color: 0x46A028, emissive: 0x123008, specular: 0x2a4a1c, shininess: 10 });
const botMat = new THREE.MeshPhongMaterial({ color: 0x235E16, emissive: 0x081a05, shininess: 4 });
const rimMat = new THREE.LineBasicMaterial({ color: 0xC8D64B });
const hwR = SLAB_W / 2 - 0.004, hdR = SLAB_D / 2 - 0.004;
const rimGeo = new THREE.BufferGeometry().setFromPoints([
  V(-hwR, 0.004, -hdR), V(hwR, 0.004, -hdR), V(hwR, 0.004, hdR), V(-hwR, 0.004, hdR)
]);

const niGeo = new THREE.SphereGeometry(NI_R, 22, 14, 0, Math.PI * 2, 0, Math.PI / 2);
// white base colour tinted per-instance; emissive lifts the green so it stays vivid
const niMat = new THREE.MeshPhongMaterial({
  color: 0xffffff, emissive: 0x143808, specular: 0x8CD46A, shininess: 26
});
const GREEN = new THREE.Color(0x5FBE34);
const HILITE = new THREE.Color(0xFF8C3A);

const niPositions = [];
for (let j = 0; j < NZ; j++) {
  for (let i = 0; i < NX; i++) {
    const x = (i - (NX - 1) / 2) * SPX + (j % 2 ? 0.17 : -0.17);
    const z = (j - (NZ - 1) / 2) * SPZ;
    niPositions.push(V(x, -0.03, z));
  }
}

const NI_INFO = {
  title: 'Ni — surface atom',
  tooltip: 'Ni — surface atom',
  body: 'Each bump is a nickel atom. Its partially filled d-orbitals overlap with H₂ and with the ethylene π cloud, weakening the H–H and C=C bonds so they break at far lower temperature than in the gas phase. The Ni–H and Ni–C bonds formed here hold the fragments next to each other until they combine.'
};

function buildSlab(parent) {
  const slab = new THREE.Mesh(slabGeo, [sideMat, sideMat, topMat, botMat, sideMat, sideMat]);
  slab.position.y = -SLAB_T / 2;
  parent.add(slab);
  parent.add(new THREE.LineLoop(rimGeo, rimMat));
  const inst = new THREE.InstancedMesh(niGeo, niMat, NX * NZ);
  const m = new THREE.Matrix4();
  for (let k = 0; k < niPositions.length; k++) {
    const p = niPositions[k];
    m.makeTranslation(p.x, p.y, p.z);
    inst.setMatrixAt(k, m);
    inst.setColorAt(k, GREEN);
  }
  inst.instanceMatrix.needsUpdate = true;
  if (inst.instanceColor) inst.instanceColor.needsUpdate = true;
  parent.add(inst);
  return inst;
}

/* atoms / bonds */
const H_R = 0.185, C_R = 0.33, ROD_R = 0.055;
const hGeo = new THREE.SphereGeometry(H_R, 24, 16);
const cGeo = new THREE.SphereGeometry(C_R, 28, 20);
const rodGeo = new THREE.CylinderGeometry(ROD_R, ROD_R, 1, 14);
const rodThinGeo = new THREE.CylinderGeometry(0.026, 0.026, 1, 10);

function mkHMat(t) {
  return new THREE.MeshPhongMaterial({
    color: 0xffffff, specular: 0xffffff, shininess: 70, emissive: 0x3c3c3c, transparent: !!t
  });
}
function mkCMat(t) {
  return new THREE.MeshPhongMaterial({
    color: 0x3A3A3A, specular: 0x9a9a9a, shininess: 45, emissive: 0x0b0b0b, transparent: !!t
  });
}
function mkRMat(t) {
  return new THREE.MeshPhongMaterial({
    color: 0xCCCCCC, specular: 0x888888, shininess: 30, emissive: 0x303030, transparent: !!t
  });
}
const hMatS = mkHMat(false), cMatS = mkCMat(false), rodMatS = mkRMat(false);
const rodFaintS = new THREE.MeshPhongMaterial({ color: 0x9a9a9a, shininess: 5, transparent: true, opacity: 0.55 });

const _dv = new THREE.Vector3();
function setRod(mesh, a, b, offset) {
  _dv.subVectors(b, a);
  const len = _dv.length();
  if (len < 1e-5) { mesh.visible = false; return; }
  mesh.position.copy(a).addScaledVector(_dv, 0.5);
  if (offset) mesh.position.add(offset);
  mesh.quaternion.setFromUnitVectors(UPV, _dv.clone().normalize());
  mesh.scale.set(1, len, 1);
}
function setOp(mesh, o) { mesh.material.opacity = o; mesh.visible = o > 0.02; }

function addSphereS(parent, geo, mat, pos) {
  const m = new THREE.Mesh(geo, mat); m.position.copy(pos); parent.add(m); return m;
}
function addRodS(parent, a, b, offset, geo, mat) {
  const m = new THREE.Mesh(geo || rodGeo, mat || rodMatS);
  setRod(m, a, b, offset); parent.add(m); return m;
}

/* ── arrow factories ─────────────────────────────────────────────────── */
function mkStraightArrow(parent, origin, len) {
  const a = new THREE.ArrowHelper(V(0, -1, 0), origin, len, 0x111111, 0.26, 0.155);
  a.line.material = a.line.material.clone();
  a.cone.material = a.cone.material.clone();
  a.line.material.transparent = true;
  a.line.material.linewidth = 2;
  a.cone.material.transparent = true;
  a.userData.setOp = o => {
    a.line.material.opacity = o; a.cone.material.opacity = o; a.visible = o > 0.02;
  };
  parent.add(a); return a;
}
function mkShaftArrow(parent, origin, len) {
  // thicker shaft than a raw ArrowHelper line, so descent arrows read clearly
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0x111111, transparent: true });
  const shaftLen = Math.max(0.05, len - 0.26);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.028, shaftLen, 10), mat);
  shaft.position.set(origin.x, origin.y - shaftLen / 2, origin.z);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.095, 0.26, 16), mat.clone());
  cone.position.set(origin.x, origin.y - shaftLen - 0.13, origin.z);
  cone.rotation.x = Math.PI;
  g.add(shaft); g.add(cone);
  g.userData.setOp = o => { shaft.material.opacity = o; cone.material.opacity = o; g.visible = o > 0.02; };
  parent.add(g); return g;
}
function mkCurvedArrow(parent, p0, p1, p2) {
  const curve = new THREE.QuadraticBezierCurve3(p0, p1, p2);
  const mat = new THREE.MeshBasicMaterial({ color: 0x111111, transparent: true });
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 28, 0.034, 8, false), mat);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.24, 14), mat.clone());
  const tan = curve.getTangent(1).normalize();
  cone.position.copy(p2).addScaledVector(tan, 0.09);
  cone.quaternion.setFromUnitVectors(UPV, tan);
  const g = new THREE.Group();
  g.add(tube); g.add(cone);
  g.userData.setOp = o => { tube.material.opacity = o; cone.material.opacity = o; g.visible = o > 0.02; };
  parent.add(g); return g;
}

/* ── molecular geometry constants ─────────────────────────────────────── */
const e1 = V(1, 0, 0);
const e2 = V(0, 0.94, -0.34).normalize();
const DIR = (a, b) => e1.clone().multiplyScalar(a).addScaledVector(e2, b).normalize();
const CH = 0.62, HALF_CC = 0.45;

function freeEthylene(center) {
  const c0 = center.clone().add(V(-HALF_CC, 0, 0));
  const c1 = center.clone().add(V(HALF_CC, 0, 0));
  return {
    c0, c1, h: [
      c0.clone().addScaledVector(DIR(-0.5, 0.866), CH),
      c0.clone().addScaledVector(DIR(-0.5, -0.866), CH),
      c1.clone().addScaledVector(DIR(0.5, 0.866), CH),
      c1.clone().addScaledVector(DIR(0.5, -0.866), CH)
    ]
  };
}
function ethane(center) {
  const c0 = center.clone().add(V(-HALF_CC, 0, 0));
  const c1 = center.clone().add(V(HALF_CC, 0, 0));
  const mk = (c, sx, adeg) => {
    const a = THREE.MathUtils.degToRad(adeg);
    return c.clone().addScaledVector(V(0.333 * sx, 0.943 * Math.cos(a), 0.943 * Math.sin(a)), CH);
  };
  return {
    c0, c1, h: [
      mk(c0, -1, 90), mk(c0, -1, 210), mk(c1, 1, 30), mk(c1, 1, 150),
      mk(c0, -1, 330), mk(c1, 1, 270)
    ]
  };
}

const ADS_C0 = V(-HALF_CC, 0.55, 0), ADS_C1 = V(HALF_CC, 0.55, 0);
const ADS_H = [
  ADS_C0.clone().addScaledVector(V(-0.5, 0.5, 0.71).normalize(), CH),
  ADS_C0.clone().addScaledVector(V(-0.5, 0.5, -0.71).normalize(), CH),
  ADS_C1.clone().addScaledVector(V(0.5, 0.5, 0.71).normalize(), CH),
  ADS_C1.clone().addScaledVector(V(0.5, 0.5, -0.71).normalize(), CH)
];
const ADS_H4 = ADS_C0.clone().addScaledVector(V(-0.92, 0.42, 0).normalize(), CH);
const ADS_H5 = ADS_C1.clone().addScaledVector(V(0.92, 0.42, 0).normalize(), CH);

const FREE_C = V(0, 2.30, 0.2);
const ETHANE_C = V(0, 1.95, 0.2);
const EXIT_C = V(0, 3.20, 0.2);
const FREE = freeEthylene(FREE_C);
const ETH = ethane(ETHANE_C);
const EXIT = ethane(EXIT_C);

/* surface hollow slots — all safely inside the slab footprint */
const S = [
  V(-1.70, 0.22, 0.75),   // 0  ← left H2
  V(-1.18, 0.22, 0.34),   // 1  ← left H2, migrates to C0
  V(1.18, 0.22, -0.34),   // 2  ← right H2, migrates to C1
  V(1.70, 0.22, -0.76),   // 3  ← right H2
  V(-1.62, 0.22, -0.70),  // 4  pre-adsorbed
  V(1.64, 0.22, 0.52),    // 5  pre-adsorbed
  V(-0.62, 0.22, 1.08),   // 6  pre-adsorbed
  V(0.58, 0.22, -1.02)    // 7  pre-adsorbed
];

/* free H2 molecules (right + left) — centres 0.48 apart so the two white
   spheres stay clearly separate with a visible bond rod between them */
const H2_HALF = 0.24;
const HCr = V(1.62, 1.50, -0.85);
const HDr = V(0.86, 0.44, 0.26).normalize();
const H2A = HCr.clone().addScaledVector(HDr, H2_HALF);
const H2B = HCr.clone().addScaledVector(HDr, -H2_HALF);
const HCl = V(-1.78, 1.56, 0.92);
const HDl = V(0.88, 0.40, 0.26).normalize();
const H2C = HCl.clone().addScaledVector(HDl, H2_HALF);
const H2D = HCl.clone().addScaledVector(HDl, -H2_HALF);

/* ── keyframes ────────────────────────────────────────────────────────── */
const K = [
  { // 0 — (a)
    hA: H2A, hB: H2B, hC: H2C, hD: H2D, rOp: 1, lOp: 1,
    sOp: [0, 0, 0, 0, 1, 1, 1, 1],
    c0: FREE.c0, c1: FREE.c1,
    h: [FREE.h[0], FREE.h[1], FREE.h[2], FREE.h[3], S[1], S[2]],
    hop: [1, 1, 1, 1, 0, 0]
  },
  { // 1 — (b)
    hA: S[2], hB: S[3], hC: S[0], hD: S[1], rOp: 0, lOp: 0,
    sOp: [1, 1, 1, 1, 1, 1, 0, 1],
    c0: ADS_C0, c1: ADS_C1,
    h: [ADS_H[0], ADS_H[1], ADS_H[2], ADS_H[3], S[1], S[2]],
    hop: [1, 1, 1, 1, 0, 0]
  },
  { // 2 — (c)
    hA: S[2], hB: S[3], hC: S[0], hD: S[1], rOp: 0, lOp: 0,
    sOp: [1, 0, 0, 1, 1, 1, 0, 1],
    c0: ADS_C0, c1: ADS_C1,
    h: [ADS_H[0], ADS_H[1], ADS_H[2], ADS_H[3], ADS_H4, ADS_H5],
    hop: [1, 1, 1, 1, 1, 1]
  },
  { // 3 — (d)
    hA: S[2], hB: S[3], hC: S[0], hD: S[1], rOp: 0, lOp: 0,
    sOp: [0, 0, 0, 1, 0, 0, 0, 1],
    c0: ETH.c0, c1: ETH.c1,
    h: ETH.h.slice(),
    hop: [1, 1, 1, 1, 1, 1]
  },
  { // 4 — wraps back to (a)
    hA: H2A, hB: H2B, hC: H2C, hD: H2D, rOp: 1, lOp: 1,
    sOp: [0, 0, 0, 0, 1, 1, 1, 1],
    c0: EXIT.c0, c1: EXIT.c1,
    h: EXIT.h.slice(),
    hop: [1, 1, 1, 1, 1, 1]
  }
];

/* ── MAIN (single-panel, animated) scene graph ────────────────────────── */
const mainG = new THREE.Group();
scene.add(mainG);
const niMesh = buildSlab(mainG);

const halo = new THREE.Mesh(
  new THREE.TorusGeometry(0.40, 0.025, 8, 36),
  new THREE.MeshBasicMaterial({ color: 0xFF8C3A })
);
halo.rotation.x = -Math.PI / 2;
halo.visible = false;
mainG.add(halo);

function mkH() { const m = new THREE.Mesh(hGeo, mkHMat(true)); mainG.add(m); return m; }
function mkC() { const m = new THREE.Mesh(cGeo, mkCMat(true)); mainG.add(m); return m; }
function mkRod() { const m = new THREE.Mesh(rodGeo, mkRMat(true)); mainG.add(m); return m; }

const mH2A = mkH(), mH2B = mkH(), mH2Rod = mkRod();
const mH2C = mkH(), mH2D = mkH(), mH2Rod2 = mkRod();
const mS = S.map(() => mkH());
const mC0 = mkC(), mC1 = mkC();
const mMolH = [0, 1, 2, 3, 4, 5].map(() => mkH());
const mCCa = mkRod(), mCCb = mkRod();
const mCH = [0, 1, 2, 3, 4, 5].map(() => mkRod());

function mkDashed(parent) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
  const l = new THREE.Line(g, new THREE.LineDashedMaterial({
    color: 0x888888, dashSize: 0.09, gapSize: 0.07, transparent: true
  }));
  l.userData.set = (a, b) => {
    const p = g.attributes.position;
    p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z);
    p.needsUpdate = true; l.computeLineDistances(); g.computeBoundingSphere();
  };
  parent.add(l); return l;
}
const niC0 = mkDashed(mainG), niC1 = mkDashed(mainG);

const arrowA1 = mkShaftArrow(mainG, V(1.62, 1.12, -0.85), 0.92);
const arrowA2 = mkShaftArrow(mainG, V(-1.78, 1.18, 0.92), 0.95);
const arrowsB = [-0.95, 0, 0.95].map(x => mkShaftArrow(mainG, V(x, 1.98, 0.2), 1.05));
const arrowCL = mkCurvedArrow(mainG, V(-1.15, 0.38, 0.34), V(-1.05, 0.90, 0.20), V(-0.78, 0.78, 0.08));
const arrowCR = mkCurvedArrow(mainG, V(1.15, 0.38, -0.34), V(1.05, 0.90, -0.20), V(0.78, 0.78, -0.08));
const arrowD = mkCurvedArrow(mainG, V(1.32, 0.45, 0.92), V(0.98, 1.24, 0.60), V(0.42, 1.52, 0.34));

/* ── leaders + labels (main) ──────────────────────────────────────────── */
function mkLeader(parent) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
  const l = new THREE.Line(g, new THREE.LineBasicMaterial({ color: 0x111111, transparent: true }));
  l.userData.set = (a, b) => {
    const p = g.attributes.position;
    p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z);
    p.needsUpdate = true; g.computeBoundingSphere();
  };
  parent.add(l); return l;
}
// 'Ni surface' leader terminates ON a lattice atom (row j=3, col i=2 → top of dome)
const NI_ANCHOR = V(-0.51, 0.30, 0.72);
const leadNi = mkLeader(mainG); leadNi.userData.set(V(-2.34, 1.34, 1.40), NI_ANCHOR);
const leadH = mkLeader(mainG); leadH.userData.set(V(0.82, 2.70, -0.72), HCr.clone().add(V(-0.02, 0.24, 0)));
const leadMol = mkLeader(mainG);

const lblNi = addLabel('Ni surface', V(-2.78, 1.58, 1.58), { fontSize: '15px' });
const lblH = addLabel('Hydrogen', V(0.86, 2.96, -0.80), { fontSize: '15px' });
const lblMol = addLabel('Ethylene', V(-1.3, 3.1, 1.3), { fontSize: '15px' });
const lblCap = addLabel('(a)', V(1.85, -1.78, 1.85), { fontSize: '22px', bold: true });

/* ── ALL-STAGES strip (four static mini panels) ───────────────────────── */
const MINI_SCALE = 0.45, MINI_GAP = 3.15;
const RIGHT = V(Math.SQRT1_2, 0, -Math.SQRT1_2);   // screen-right in the iso pose
const allG = new THREE.Group();
const miniLabels = [];
const STAGE_VIS = [
  { pi: 1, ni: 0, h2: true, hop: [1, 1, 1, 1, 0, 0] },
  { pi: 0, ni: 1, h2: false, hop: [1, 1, 1, 1, 0, 0] },
  { pi: 0, ni: 1, h2: false, hop: [1, 1, 1, 1, 1, 1] },
  { pi: 0, ni: 0, h2: false, hop: [1, 1, 1, 1, 1, 1] }
];
const MINI_CAP = ['(a)', '(b)', '(c)', '(d)'];
const MINI_SUB = ['H₂ adsorbs &amp; splits', 'ethylene adsorbs', 'H atoms add', 'ethane leaves'];

function buildStage(idx) {
  const g = new THREE.Group();
  const inst = buildSlab(g);
  registerInteractive(inst, NI_INFO);
  const kf = K[idx], vis = STAGE_VIS[idx];

  for (let i = 0; i < S.length; i++) {
    if (kf.sOp[i] > 0.5) addSphereS(g, hGeo, hMatS, S[i]);
  }
  if (vis.h2) {
    addSphereS(g, hGeo, hMatS, H2A); addSphereS(g, hGeo, hMatS, H2B); addRodS(g, H2A, H2B);
    addSphereS(g, hGeo, hMatS, H2C); addSphereS(g, hGeo, hMatS, H2D); addRodS(g, H2C, H2D);
    mkShaftArrow(g, V(1.62, 1.12, -0.85), 0.92);
    mkShaftArrow(g, V(-1.78, 1.18, 0.92), 0.95);
  }
  const c0 = kf.c0, c1 = kf.c1;
  addSphereS(g, cGeo, cMatS, c0); addSphereS(g, cGeo, cMatS, c1);
  if (vis.pi > 0.5) {
    const off = e2.clone().multiplyScalar(0.07);
    addRodS(g, c0, c1, off);
    addRodS(g, c0, c1, off.clone().negate());
  } else {
    addRodS(g, c0, c1);
  }
  for (let i = 0; i < 6; i++) {
    if (vis.hop[i] < 0.5) continue;
    const hp = kf.h[i];
    addSphereS(g, hGeo, hMatS, hp);
    addRodS(g, (i === 0 || i === 1 || i === 4) ? c0 : c1, hp);
  }
  if (vis.ni) {
    addRodS(g, c0, V(c0.x - 0.10, 0.12, c0.z + 0.05), null, rodThinGeo, rodFaintS);
    addRodS(g, c1, V(c1.x + 0.10, 0.12, c1.z - 0.05), null, rodThinGeo, rodFaintS);
  }
  if (idx === 1) [-0.95, 0, 0.95].forEach(x => mkShaftArrow(g, V(x, 1.98, 0.2), 1.05));
  if (idx === 2) {
    mkCurvedArrow(g, V(-1.15, 0.38, 0.34), V(-1.05, 0.90, 0.20), V(-0.78, 0.78, 0.08));
    mkCurvedArrow(g, V(1.15, 0.38, -0.34), V(1.05, 0.90, -0.20), V(0.78, 0.78, -0.08));
  }
  if (idx === 3) mkCurvedArrow(g, V(1.32, 0.45, 0.92), V(0.98, 1.24, 0.60), V(0.42, 1.52, 0.34));

  g.scale.setScalar(MINI_SCALE);
  g.position.copy(RIGHT).multiplyScalar((idx - 1.5) * MINI_GAP);
  allG.add(g);

  const capLocal = V(1.85, -1.55, 1.85).multiplyScalar(MINI_SCALE).add(g.position);
  const subLocal = V(1.85, -2.35, 1.85).multiplyScalar(MINI_SCALE).add(g.position);
  const lc = addLabel(MINI_CAP[idx], capLocal, { fontSize: '18px', bold: true });
  const ls = addLabel(MINI_SUB[idx], subLocal, { fontSize: '11.5px', color: '#444' });
  lc.div.style.opacity = '0'; ls.div.style.opacity = '0';
  miniLabels.push(lc, ls);
  return g;
}
for (let i = 0; i < 4; i++) buildStage(i);

/* ── state machine ────────────────────────────────────────────────────── */
let curP = 0, targetP = 0, wrapForward = false, playing = false, speed = 0.5;
let mainVisible = true;

const STEP_CAP = ['(a)', '(b)', '(c)', '(d)'];
const STEP_TITLES = [
  'Hydrogen adsorbs and dissociates',
  'Ethylene adsorbs, π bond breaks',
  'Surface hydrogens migrate and add',
  'Ethane desorbs'
];
const STEP_BODY = [
  'Two H₂ molecules drop onto the nickel lattice; each H–H bond breaks and the separated H atoms sit bonded in surface hollows.',
  'Ethylene descends onto the surface. Its C=C π bond opens, leaving a C–C single bond with each carbon now bonded to Ni and the hydrogens bent upward.',
  'Adsorbed H atoms diffuse across the nickel and collide with the bound carbons; curved arrows show each new C–H bond forming as the Ni–C bonds weaken.',
  'With both carbons saturated, ethane no longer binds the metal and lifts off, leaving the nickel surface unchanged and available for the next cycle.'
];

const _t0 = new THREE.Vector3(), _t1 = new THREE.Vector3(), _t2 = new THREE.Vector3(), _t3 = new THREE.Vector3();
const _hp = [0, 1, 2, 3, 4, 5].map(() => new THREE.Vector3());
const _molCenter = new THREE.Vector3();
const _anchor = new THREE.Vector3(), _lend = new THREE.Vector3();

function win(p, c) {
  const dd = Math.min(Math.abs(p - c), Math.abs(p - c + 4), Math.abs(p - c - 4));
  return clamp01((0.44 - dd) / 0.26);
}

function applyState(p) {
  const pp = Math.max(0, Math.min(3.9999, p));
  const s = Math.floor(pp), ur = pp - s, u = ur * ur * (3 - 2 * ur);
  const A = K[s], B = K[s + 1];
  const L = (a, b) => a + (b - a) * u;
  const M = mainVisible ? 1 : 0;

  const molOp = (s === 0 ? clamp01(ur * 3.5)
    : s === 3 ? clamp01(1 - (ur - 0.35) / 0.35) : 1) * M;
  const pi = s === 0 ? clamp01(1 - (ur - 0.50) / 0.30)
    : s === 3 ? clamp01((ur - 0.60) / 0.30) : 0;
  const niOp = (s === 0 ? clamp01((ur - 0.72) / 0.20) * 0.9
    : s === 1 ? 0.9 - 0.4 * u
      : s === 2 ? 0.5 * clamp01(1 - ur * 1.6) : 0) * M;

  // free H2 (right)
  _t0.copy(A.hA).lerp(B.hA, u); mH2A.position.copy(_t0);
  _t1.copy(A.hB).lerp(B.hB, u); mH2B.position.copy(_t1);
  const rOp = L(A.rOp, B.rOp) * M;
  setOp(mH2A, rOp); setOp(mH2B, rOp);
  setRod(mH2Rod, _t0, _t1); setOp(mH2Rod, rOp);

  // free H2 (left)
  _t2.copy(A.hC).lerp(B.hC, u); mH2C.position.copy(_t2);
  _t3.copy(A.hD).lerp(B.hD, u); mH2D.position.copy(_t3);
  const lOp = L(A.lOp, B.lOp) * M;
  setOp(mH2C, lOp); setOp(mH2D, lOp);
  setRod(mH2Rod2, _t2, _t3); setOp(mH2Rod2, lOp);

  // surface hydrogens
  for (let i = 0; i < S.length; i++) {
    mS[i].position.copy(S[i]);
    setOp(mS[i], L(A.sOp[i], B.sOp[i]) * M);
  }

  // molecule
  _t0.copy(A.c0).lerp(B.c0, u); mC0.position.copy(_t0);
  _t1.copy(A.c1).lerp(B.c1, u); mC1.position.copy(_t1);
  setOp(mC0, molOp); setOp(mC1, molOp);
  _molCenter.copy(_t0).add(_t1).multiplyScalar(0.5);

  const off = e2.clone().multiplyScalar(0.07 * pi);
  setRod(mCCa, _t0, _t1, off); setOp(mCCa, molOp);
  setRod(mCCb, _t0, _t1, off.clone().multiplyScalar(-1)); setOp(mCCb, molOp * pi);

  for (let i = 0; i < 6; i++) {
    _hp[i].copy(A.h[i]).lerp(B.h[i], u);
    mMolH[i].position.copy(_hp[i]);
    const o = molOp * L(A.hop[i], B.hop[i]);
    setOp(mMolH[i], o);
    setRod(mCH[i], (i === 0 || i === 1 || i === 4) ? _t0 : _t1, _hp[i]);
    setOp(mCH[i], o);
  }

  // Ni–C dashed bonds
  niC0.userData.set(_t0, V(_t0.x - 0.10, 0.12, _t0.z + 0.05));
  niC1.userData.set(_t1, V(_t1.x + 0.10, 0.12, _t1.z - 0.05));
  niC0.material.opacity = niOp; niC0.visible = niOp > 0.02;
  niC1.material.opacity = niOp; niC1.visible = niOp > 0.02;

  // arrows
  const oa = win(pp, 0) * M, ob = win(pp, 1) * M, oc = win(pp, 2) * M, od = win(pp, 3) * M;
  arrowA1.userData.setOp(oa); arrowA2.userData.setOp(oa);
  arrowsB.forEach(a => a.userData.setOp(ob));
  arrowCL.userData.setOp(oc); arrowCR.userData.setOp(oc);
  arrowD.userData.setOp(od);

  // labels
  lblNi.div.style.opacity = String(M);
  leadNi.material.opacity = M; leadNi.visible = M > 0.02;
  lblCap.div.style.opacity = String(M);

  lblH.div.style.opacity = String(oa);
  leadH.material.opacity = oa; leadH.visible = oa > 0.02;

  const adsorbed = pp > 1.15 && pp < 2.85;
  if (adsorbed) {
    _anchor.set(1.70, -0.30, 1.70);
    _lend.set(0.25, 0.55, 0.32);
    lblMol.div.innerHTML = 'Ethylene adsorbed on<br>surface breaking &pi; bonds';
  } else {
    _anchor.copy(_molCenter).add(V(-1.35, 0.85, 1.35));
    _lend.copy(_molCenter).add(V(-0.50, 0.36, 0.18));
    lblMol.div.innerHTML = (pp > 2.85) ? 'Ethane (C<sub>2</sub>H<sub>6</sub>)' : 'Ethylene';
  }
  lblMol.pos.copy(_anchor);
  lblMol.div.style.opacity = String(molOp);
  leadMol.userData.set(_anchor.clone().addScaledVector(_lend.clone().sub(_anchor).normalize(), 0.32), _lend);
  leadMol.material.opacity = molOp; leadMol.visible = molOp > 0.02;

  lblCap.div.innerHTML = STEP_CAP[Math.round(pp) % 4];
}

/* ── initial pose + camera ────────────────────────────────────────────── */
applyState(0);
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.62
});

/* ── Ni atom picking (main lattice tints; mini lattices just explain) ─── */
let pickedIdx = -1;
registerInteractive(niMesh, {
  ...NI_INFO,
  onClick: (hit) => {
    if (hit && typeof hit.instanceId === 'number') {
      if (pickedIdx >= 0) niMesh.setColorAt(pickedIdx, GREEN);
      pickedIdx = hit.instanceId;
      niMesh.setColorAt(pickedIdx, HILITE);
      niMesh.instanceColor.needsUpdate = true;
      const p = niPositions[pickedIdx];
      halo.position.set(p.x, 0.02, p.z);
      halo.visible = true;
    }
  }
});

/* ── UI wiring ────────────────────────────────────────────────────────── */
document.getElementById('btnReset').style.display = '';
const btns = ['stepA', 'stepB', 'stepC', 'stepD'].map(id => document.getElementById(id));
const capBig = document.getElementById('capBig');
const narrTitle = document.getElementById('narrTitle');
const narrBody = document.getElementById('narrBody');
const btnPlay = document.getElementById('btnPlay');
const btnAll = document.getElementById('btnAll');
let shownStep = -1;

function refreshUI(idx) {
  if (idx === shownStep) return;
  shownStep = idx;
  btns.forEach((b, i) => b.classList.toggle('active', i === idx));
  capBig.textContent = STEP_CAP[idx];
  narrTitle.textContent = STEP_TITLES[idx];
  narrBody.textContent = STEP_BODY[idx];
}
refreshUI(0);

function stopPlay() {
  playing = false;
  btnPlay.textContent = '▶ Play catalytic cycle';
  btnPlay.classList.remove('active');
}

function setAllStages(on) {
  if (on) {
    if (!mainVisible) return;
    stopPlay();
    mainVisible = false;
    scene.remove(mainG);
    scene.add(allG);
    miniLabels.forEach(l => { l.div.style.opacity = '1'; });
    btnAll.textContent = '◧ Show single stage';
    btnAll.classList.add('active');
    applyState(curP);
    setCameraView({
      projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 },
      rollDeg: 0, heightFraction: 0.78
    });
  } else {
    if (mainVisible) return;
    mainVisible = true;
    scene.remove(allG);
    scene.add(mainG);
    miniLabels.forEach(l => { l.div.style.opacity = '0'; });
    btnAll.textContent = '▦ Show all four stages';
    btnAll.classList.remove('active');
    applyState(curP);
    setCameraView({
      projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 },
      rollDeg: 0, heightFraction: 0.62
    });
  }
}

function goToStep(i) {
  setAllStages(false);
  stopPlay();
  if (i === 0 && curP > 2.2) { targetP = 4; wrapForward = true; }
  else { targetP = i; wrapForward = false; }
  refreshUI(i);
}
btns.forEach((b, i) => b.addEventListener('click', () => goToStep(i)));

btnPlay.addEventListener('click', () => {
  setAllStages(false);
  playing = !playing;
  btnPlay.textContent = playing ? '❚❚ Pause cycle' : '▶ Play catalytic cycle';
  btnPlay.classList.toggle('active', playing);
});
btnAll.addEventListener('click', () => setAllStages(mainVisible));
document.getElementById('speed').addEventListener('input', e => {
  speed = parseFloat(e.target.value);
});

/* ── driver loop (state only; scaffold owns rendering) ────────────────── */
let _prev = performance.now();
function tickState() {
  requestAnimationFrame(tickState);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _prev) / 1000);
  _prev = now;

  if (playing) {
    curP += dt * speed;
    while (curP >= 4) curP -= 4;
    targetP = curP;
    refreshUI(Math.round(curP) % 4);
  } else {
    const diff = targetP - curP;
    if (Math.abs(diff) > 1e-4) {
      const stepAmt = Math.sign(diff) * Math.min(Math.abs(diff), dt * Math.max(0.8, speed * 1.6));
      curP += stepAmt;
    } else if (wrapForward) {
      curP = 0; targetP = 0; wrapForward = false;
    }
  }
  applyState(curP);
}
tickState();
